const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deletingProjectId=null,projectOpening=false,projectOpenRevision=0;
let editRevision=0,savePending=0;
let videoCapabilities={reference:{},first_frame:[],strategies:{}},modelCatalog={images:[],videos:[]};
function strategy(mode){return videoCapabilities.strategies?.[mode]||{label:mode==='reference'?ui('参考资产'):ui('首帧图片'),models:mode==='reference'?Object.keys(videoCapabilities.reference):videoCapabilities.first_frame,inputs:mode==='reference'?['assets']:['first_frame']}}
