function modeOptions(current,inherit=false){return (inherit?ui`<option value="inherit" ${current==='inherit'?'selected':''}>跟随项目（${esc(ui(strategy(projectVideoMode()).label))}）</option>`:'')+Object.entries(videoCapabilities.strategies).map(([mode,spec])=>`<option value="${mode}" ${current===mode?'selected':''}>${esc(ui(spec.label))}</option>`).join('')}
