function projectVideoMode(){return p.video_mode||p.shots[0]?.video_mode||'first_frame'}
function effectiveVideoMode(shot){return shot.video_override?.mode||p.video_mode||shot.video_mode||'first_frame'}
function shotVideoRoute(shot){const override=shot.video_override,mode=effectiveVideoMode(shot),current=canonicalVideoModel(override?.model||p.video_model),available=videoModelsFor(mode);return ui`<div class="shot-route-controls"><select id="shotVideoMode" aria-label="镜头生成方案" title="默认跟随项目，可独立设置">${modeOptions(override?.mode||'inherit',true)}</select>${override?ui`<select id="shotVideoModel" aria-label="镜头独立视频模型" title="${esc(current)}">${!available.includes(current)?ui`<option value="${esc(current)}">请选择兼容模型</option>`:''}${available.map(m=>`<option value="${esc(m)}" ${m===current?'selected':''}>${esc(videoModelLabel(m))}</option>`).join('')}</select>`:''}${shotResolutionControls(shot,current)}</div>`}
function renderVideoSettings(){const mode=projectVideoMode();$('#video_mode').innerHTML=modeOptions(mode);$('#video_model').innerHTML=allVideoModelOptions(mode,p.video_model);$('#video_model').value=mode+'|'+canonicalVideoModel(p.video_model);renderResolutionSettings();document.body.classList.toggle('reference-video-mode',!needsFirstFrame(mode))}
const resolutionLabels={'240p':ui('超低清预览 · 240P'),'360p':ui('预览 · 360P'),'480p':ui('预览 · 480P'),'720p':'720P','768p':ui('原生 768P'),'1080p':'1080P','2k':'2K','custom':ui('自定义尺寸')};
function isPikaVideo(model){return String(model||'').startsWith('Pika-H3-Flex-6step-')}
function adaptPikaResolution(model,shot){const cloud=videoModelSpec(model)?.provider;if(cloud){const current=shot?(shot.video_resolution||shot.video_override?.resolution||p.video_resolution):p.video_resolution,allowed=cloud==='minimax'?['768p','2k']:['480p','720p','1080p'];if(current&&!allowed.includes(current.preset)){if(shot){shot.video_resolution=null;if(shot.video_override)shot.video_override.resolution=null}else p.video_resolution=null}return}if(!isPikaVideo(model))return;const current=shot?(shot.video_resolution||shot.video_override?.resolution||p.video_resolution):p.video_resolution;if(current&&!['480p','768p'].includes(current.preset)){if(shot)shot.video_resolution={preset:'768p'};else p.video_resolution={preset:'768p'}}}
function videoModelSpec(model){return modelCatalog.videos.find(m=>m.id===model)}
function canonicalVideoModel(model){return videoModelSpec(model)?.canonical_model||model}
function videoModelLabel(model){return ({'h3_redcraft_a2a_closeup_r2v':ui('RedCraft H3 · 侧面近景 R2V（导入，未验证）'),'MiniMaxH3-RedCraft-A2A-beta1-8step-R2V-2K':ui('RedCraft H3 A2A · 8步 · 资产参考'),'MiniMaxH3-RedCraft-A2A-beta1-8step-I2V-2K':ui('RedCraft H3 A2A · 8步 · 首帧'),'Pika-H3-Flex-6step-T2V-I2V':ui('Pika H3 Flex · 6步 · 文生/首帧'),'Pika-H3-Flex-6step-R2V':ui('Pika H3 Flex · 6步 · 资产参考')})[model]||videoModelSpec(model)?.display_name||model}
function resolutionOptions(value,inherit=false,model=p?.video_model){const cloud=videoModelSpec(model)?.provider,options=Object.entries(resolutionLabels).filter(([key])=>cloud?(cloud==='minimax'?['768p','2k']:['480p','720p','1080p']).includes(key):isPikaVideo(model)?['480p','768p'].includes(key):key!=='768p');return `<option value="${inherit?'inherit':'default'}">${inherit?ui('跟随项目 / 模型默认'):ui('工作流默认')}</option>`+options.map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('')}
function displayedResolution(shot){const model=shot?(shot.video_override?.model||p.video_model):p.video_model;return shot?.video_resolution||shot?.video_override?.resolution||p.video_resolution||(videoModelSpec(model)?.legacy_resolution?{preset:videoModelSpec(model).legacy_resolution}:null)}
function resolutionDimensions(config,model=p?.video_model){if(!config)return ui('沿用所选工作流尺寸');if(config.preset==='custom')return `${config.width} × ${config.height}`;let dims=isPikaVideo(model)&&config.preset==='480p'?[832,480]:(modelCatalog.video_resolutions||{})[config.preset];if(!dims)return resolutionLabels[config.preset]||'';if(p.ratio==='9:16')dims=[dims[1],dims[0]];return dims.join(' × ')}
function renderResolutionSettings(){const el=$('#video_resolution');if(!el)return;const supported=videoModelSpec(p.video_model)?.supports_resolution||false,config=displayedResolution();el.innerHTML=resolutionOptions(config?.preset||'default',false,p.video_model);el.value=config?.preset||'default';el.disabled=!supported;$('#videoSizeFields').hidden=!supported||config?.preset!=='custom';$('#videoWidth').value=config?.width||720;$('#videoHeight').value=config?.height||480;$('#videoResolutionNote').textContent=supported?resolutionDimensions(config,p.video_model)+(isPikaVideo(p.video_model)?ui(' · 原生480P/768P，5–15整秒'):ui(' · 仅影响新任务')):ui('此模型沿用工作流默认尺寸')}
function shotResolutionControls(shot,model){if(!videoModelSpec(model)?.supports_resolution)return ui('<span class="sub">工作流默认尺寸</span>');const own=shot.video_resolution||shot.video_override?.resolution;return ui`<select id="shotVideoResolution" aria-label="镜头分辨率">${resolutionOptions(own?.preset||'inherit',true,model)}</select>${own?.preset==='custom'?ui`<input id="shotVideoWidth" type="number" min="128" max="4096" step="2" value="${own.width}" aria-label="镜头视频宽度"><span>×</span><input id="shotVideoHeight" type="number" min="128" max="4096" step="2" value="${own.height}" aria-label="镜头视频高度">`:''}<span class="resolution-note">${esc(resolutionDimensions(displayedResolution(shot),model))}${isPikaVideo(model)?ui(' · 5–15整秒'):''}</span>`}
function selectedResolution(value,config){return ['default','inherit'].includes(value)?null:value==='custom'?{preset:value,width:config?.width||720,height:config?.height||480}:{preset:value}}
function frontendResources(project=p){return [...project.assets,...project.shots,...project.assets.flatMap(a=>[...(a.looks||[]),...((a.looks||[]).flatMap(l=>l.garment_reference?[l.garment_reference]:[])),...(a.body_reference?[a.body_reference]:[])])]}
function audioAssets(){return p.assets.filter(a=>a.type==='音频')}
function resolvedAudio(shot){const source=shot.audio_source;if(source?.type==='asset'){const a=audioAssets().find(a=>a.id===source.asset_id);return {url:a?.audio,duration:a?.audio_duration||a?.versions?.find(v=>v.url===a.audio)?.duration,label:a?.name||ui('音频资产缺失')}}return {url:source?.url||shot.reference_audio,duration:shot.versions?.find(v=>v.url===source?.url)?.duration||shot.audio_duration,label:ui('当前对白音频')}}
function audioPlayer(url){return url?`<audio controls preload="metadata" data-read-audio="${esc(url)}" src="${esc(url)}"></audio>`:ui('<span class="sub">尚无音频</span>')}
function speechControls(shot){const selected=resolvedAudio(shot);return ui`<div class="speech-controls ${effectiveVideoMode(shot)==='music'?'music-reference':''}"><div class="speech-row"><label>说话人<select id="speakerId"><option value="">选择人物</option>${p.assets.filter(a=>a.type==='角色').map(a=>`<option value="${esc(a.id)}" ${shot.speaker_id===a.id?'selected':''}>${esc(a.name)}${a.voice_asset_id?'':ui('（未设声音）')}</option>`).join('')}</select></label>${voiceSelector(shot)}<input id="speechEmotion" aria-label="配音语气" placeholder="语气，例如轻声、迟疑" value="${esc(shot.speech_emotion||'')}"></div><div class="speech-row"><input id="speechDialogue" aria-label="本镜台词" maxlength="300" placeholder="本镜台词：单镜单说话人，最多300字" value="${esc(shot.dialogue||'')}"><button id="generateSpeech" ${running(shot.id,'audio')?'disabled':''}>${running(shot.id,'audio')?ui('配音生成中…'):ui('生成配音 · IndexTTS')}</button></div><div class="speech-row"><label>采用音频<select id="audioSource"><option value="current" ${shot.audio_source?.type!=='asset'?'selected':''}>本镜配音／直接上传</option>${audioAssets().map(a=>`<option value="${esc(a.id)}" ${shot.audio_source?.asset_id===a.id?'selected':''}>${esc(a.name)}${a.audio?'':ui('（未上传）')}</option>`).join('')}</select></label><button type="button" data-upload-guide="audio">上传音频</button>${selected.duration?ui`<span class="sub">音频 ${Number(selected.duration).toFixed(1)}秒${Math.abs(selected.duration-Number(shot.duration||4))>.6?ui(' · 与镜头时长不同'):''}</span>`:''}</div>${selected.duration&&Math.abs(selected.duration-Number(shot.duration||4))>.6?ui`<button id="useAudioDuration" >采用音频时长</button>`:''}${audioPlayer(selected.url)}<div class="speech-versions">${versions(shot,'audio')}</div><small>${effectiveVideoMode(shot)==='music'?ui('指定音乐驱动：使用已选音频资产或上传音乐，不做对白配音。'):ui('指定音频驱动：使用已选对白音频；可由角色音色＋IndexTTS生成，也可上传。')}不会自动裁切或变速。</small></div>`}
function cloudReferenceControls(shot){const model=shot.video_override?.model||p.video_model;if(effectiveVideoMode(shot)!=='reference'||!videoModelSpec(model)?.supports_media_reference)return '';return ui`<div class="guide-inputs"><label><input type="checkbox" data-cloud-ref="cloud_use_audio" ${shot.cloud_use_audio?'checked':''}>引用所选音频</label><button type="button" data-upload-guide="audio">上传参考音频</button>${shot.cloud_use_audio?ui`<details><summary>配音与已有音频</summary>${speechControls(shot)}</details>`:''}<label><input type="checkbox" data-cloud-ref="cloud_use_video" ${shot.cloud_use_video?'checked':''}>引用参考视频</label><button type="button" data-upload-guide="video">上传参考视频</button>${shot.reference_video?ui('<button type="button" data-preview-guide="video">查看</button><button type="button" data-clear-guide="video">移除</button>'):''}<small class="sub">音频直接传入；视频由平台生成临时链接，需要服务配置中的素材公网地址。未勾选的素材不会使用。提示词中用“音频1”“视频1”说明用途。</small></div>`}
function guideInputs(shot){if(effectiveVideoMode(shot)==='reference'&&videoModelSpec(shot.video_override?.model||p.video_model)?.supports_media_reference)return cloudReferenceControls(shot);const inputs=strategy(effectiveVideoMode(shot)).inputs;let result=inputs.includes('audio')?speechControls(shot):`<div class="sound-mode-note">${['upscale','interpolate'].includes(effectiveVideoMode(shot))?ui('沿用输入视频音轨，不引用角色音色或对白音频。'):ui('原生有声：模型自行生成声音，不引用角色声音参考或已选对白音频；台词由视频提示词描述。')}</div>`;if(inputs.includes('video')){const field='reference_video';result+=ui`<div class="guide-inputs"><span>参考视频${shot[field]?ui('已就绪'):(shot.video&&['upscale','interpolate'].includes(effectiveVideoMode(shot))?ui('：使用当前镜头视频'):ui('未上传'))}</span><button type="button" data-upload-guide="video">${shot[field]?ui('更换'):ui('上传')}视频</button>${shot[field]?ui('<button type="button" data-preview-guide="video">查看</button><button type="button" data-clear-guide="video">移除</button>'):''}</div>`}return result+cloudReferenceControls(shot)}
async function uploadGuide(shot,kind){const input=document.createElement('input');input.type='file';input.accept=kind==='audio'?'audio/*':'video/*';const project=p;input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>48*1024*1024){toast(ui('参考音视频最多48MB'));return}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const result=await api('projects/'+project.id+'/upload-media',{kind,data});if(p?.id!==project.id){toast(ui('素材已上传，项目已切换，请重新选择素材'));return}const current=p.shots.find(s=>s.id===shot.id);if(current){if(kind==='audio'){const id=newResourceId();(current.versions??=[]).push({id,kind:'audio',url:result.url,created:Date.now()/1000,duration:result.duration,prompt:'上传对白音频'});current.audio=result.url;current.audio_duration=result.duration;current.audio_source={type:'upload',url:result.url,version_id:id};delete current.reference_audio}else current.reference_video=result.url;change();render()}}catch(e){toast(e.message)}};input.click()}
let p,tab='story',selected=null,jobs=[],dirty=false,saving=Promise.resolve(),editing=false,models=[],mediaBase={};
const durationLine=/^(?:Duration|时长)\s*[:：]\s*(\d+(?:\.\d+)?)\s*(?:seconds?|s|秒)\s*$/gim;
function promptDuration(text){return [...String(text||'').matchAll(durationLine)][0]?.[1]}
function writeDuration(s,value){
const n=Number(value);if(!Number.isFinite(n)||n<=0)return false;
s.duration=n;if(s.prompt_format==='huobao-native-v1'||s.prompt_format==='h3-structured-v2')return true;s.video_prompt=`Duration: ${n}s`+(String(s.video_prompt||'').replace(durationLine,'').replace(/^[\r\n]+/,'')?'\n'+String(s.video_prompt||'').replace(durationLine,'').replace(/^[\r\n]+/,''):'');return true;
}
function mediaVersionIds(shot){return (shot.versions||[]).filter(v=>v.kind==='image'||v.kind==='video'||v.kind==='audio').map(v=>String(v.id))}
function readState(project){return project.media_read||{}}
function hasNewMedia(project,shot){return mediaVersionIds(shot).some(id=>!readState(project)[id])}
async function markShotRead(project,shot,refresh=true){
const ids=mediaVersionIds(shot).filter(id=>!readState(project)[id]);if(!ids.length)return;
try{const result=await api('projects/'+project.id+'/read-media',{version_ids:ids});if(p?.id===project.id){p.media_read={...p.media_read,...result.media_read};if(refresh&&!dirty)render();else for(const el of document.querySelectorAll('[data-version]'))if(ids.includes(el.dataset.version)){el.dataset.unread='false';el.querySelectorAll('.shot-new-dot').forEach(dot=>dot.remove())}}}catch(e){toast(ui('已读状态未保存：')+e.message)}
}
function captureBase(){mediaBase=Object.fromEntries(frontendResources(p).map(s=>[s.id,{image:s.image,video:s.video,audio:s.audio,audio_source:s.audio_source}]))}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const x=await r.json();if(r.status===401){location.href='/login';throw Error(ui('请先登录片场'))}if(!r.ok)throw Error(x.error||ui('请求失败'));return x}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6000)}
function change(){editRevision++;dirty=true;$('#saved').textContent=ui('有修改，正在保存…');clearTimeout(change.timer);change.timer=setTimeout(()=>save().catch(e=>toast(e.message)),600)}
async function save(){
clearTimeout(change.timer);if(!p||!dirty)return saving;
const body=structuredClone(p);dirty=false;savePending++;
saving=saving.catch(()=>{}).then(()=>{body._media_base=structuredClone(mediaBase);return api('projects/'+body.id+'/save',body)}).then(result=>{
if(p?.id===body.id){mediaBase=Object.fromEntries(frontendResources(result).map(s=>[s.id,{image:s.image,video:s.video,audio:s.audio,audio_source:s.audio_source}]));$('#saved').textContent=dirty?ui('正在保存…'):ui('✓ 已保存到本机')}
}).catch(e=>{if(p?.id===body.id){dirty=true;$('#saved').textContent=ui('保存失败')}throw e}).finally(()=>{savePending--});return saving;
}
function canApplyProject(pid,revision,latest){return !projectOpening&&p?.id===pid&&!deletingProjectId&&!dirty&&!savePending&&editRevision===revision&&!document.activeElement?.matches('textarea,input,select')&&![...document.querySelectorAll('audio,video')].some(el=>!el.paused)&&(latest.updated||0)>=(p.updated||0)}
async function list(){const list=await api('projects');$('#projects').disabled=!list.length;$('#projects').innerHTML=list.sort((a,b)=>b.updated-a.updated).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');if(p)$('#projects').value=p.id;return list}
function rememberProjectView(){if(!p)return;try{localStorage.setItem('shotdesk:view:'+p.id,JSON.stringify({tab,selected,assetCategory,assetSelected}))}catch{}}
function restoreProjectView(project){let view={};try{const saved=JSON.parse(localStorage.getItem('shotdesk:view:'+project.id)||'{}');if(saved&&typeof saved==='object')view=saved}catch{}tab=['story','assets','shots'].includes(view.tab)?view.tab:'story';selected=project.shots.some(s=>s.id===view.selected)?view.selected:project.shots[0]?.id;assetCategory=['角色','场景','道具'].includes(view.assetCategory)?view.assetCategory:'角色';assetSelected=project.assets.some(a=>a.id===view.assetSelected&&a.type===assetCategory)?view.assetSelected:null}
function setProjectLoading(active,message=ui('正在加载项目')){const status=$('#pageLoading');status.hidden=!active;status.querySelector('[data-load-label]').textContent=message;$('#main').setAttribute('aria-busy',String(active))}
async function open(id){const revision=++projectOpenRevision;projectOpening=true;setProjectLoading(true);let rendered=false;try{await save();const jobsPromise=api('projects/'+id+'/jobs').then(value=>({value}),error=>({error}));const next=await api('projects/'+id);if(revision!==projectOpenRevision)return;restoreProjectView(next);p=next;jobs=[];captureBase();localStorage.setItem('shotdesk',id);if(![...$('#projects').options].some(o=>o.value===id))$('#projects').innerHTML=`<option value="${esc(id)}">${esc(p.name)}</option>`;$('#projects').value=id;render();rendered=true;setProjectLoading(true,ui('正在读取任务状态'));$('#main').setAttribute('aria-busy','false');const result=await jobsPromise;if(revision!==projectOpenRevision)return;if(result.error)toast(ui('项目已打开，任务状态暂未加载：')+result.error.message);else{jobs=result.value;if(!dirty&&!document.activeElement?.matches('textarea,input,select'))render()}}finally{if(revision===projectOpenRevision){projectOpening=false;setProjectLoading(false);if(!rendered&&p)$('#projects').value=p.id}}}
function target(){return p.shots.find(s=>s.id===selected)}
function running(id,kind){return jobs.find(j=>j.target_id===id&&j.kind===kind&&['queued','running','cancelling'].includes(j.status))}
function lastError(id,kind){const j=jobs.filter(j=>j.target_id===id&&j.kind===kind).sort((a,b)=>b.created-a.created)[0];return j?.status==='failed'?`<div class="error">${esc(j.error)}</div>`:''}
const field=(label,key,value,tag='textarea',extra='')=>`<label class="field"><span>${label}</span><${tag} data-field="${key}" ${extra}>${tag==='textarea'?esc(value):''}</${tag}></label>`;
function preview(url,kind){return url?kind==='video'?ui`<video controls playsinline preload="metadata" src="${esc(url)}" title="点击画面放大查看"></video><button class="media-expand" type="button" aria-label="放大查看视频">⛶</button>`:ui`<img src="${esc(url)}" alt="首帧或参考图" tabindex="0" role="button" title="点击放大查看">`:`<div class="placeholder"><div class="icon">${kind==='video'?'▷':'▧'}</div><div>${kind==='video'?ui('素材就绪后，让故事动起来'):ui('把这一刻，变成画面')}</div><small>${kind==='video'?ui('按当前方案生成，保留每次结果'):ui('生成首帧，或上传已有图片')}</small></div>`}
function orderedVersions(s,kind){return (s.versions||[]).filter(v=>v.kind===kind).sort((a,b)=>(Number(b.created)||0)-(Number(a.created)||0)||String(b.id).localeCompare(String(a.id),'en'))}
function versions(s,kind){const vs=orderedVersions(s,kind);return `<div class="versions">${vs.map((v,i)=>`<button class="${s[kind]===v.url?'selected':''}" data-version="${v.id}" data-kind="${kind}" data-unread="${!readState(p)[v.id]}" title="${esc((v.seed!==undefined?'Seed: '+v.seed+'\n':'')+(v.prompt||''))}">V${v.version??(vs.length-i)} ${s[kind]===v.url?'✓':''}${!readState(p)[v.id]?ui('<i class="shot-new-dot history-new-dot" aria-label="未查看"></i>'):''}</button>`).join('')}</div>`}
const shotScrollPositions=new Map();
function rememberShotScroll(){const list=$('.shot-list');if(list?.dataset.project)shotScrollPositions.set(list.dataset.project,{top:list.scrollTop,left:list.scrollLeft})}
function restoreShotScroll(){const list=$('.shot-list');if(!list)return;list.dataset.project=p.id;const saved=shotScrollPositions.get(p.id);if(saved){list.scrollTop=saved.top;list.scrollLeft=saved.left}if(!list.dataset.scrollTracked){list.addEventListener('scroll',rememberShotScroll,{passive:true});list.dataset.scrollTracked='true'}}
