if($('#shotVideoModel'))$('#shotVideoModel').onchange=()=>{s.video_override.model=$('#shotVideoModel').value;if(!videoModelSpec(s.video_override.model)?.supports_resolution){s.video_resolution=null;delete s.video_override.resolution}adaptPikaResolution(s.video_override.model,s);change();render()};
