async function generateBatch(kind){
const pid=p.id,mode=$('#batchMissing').checked?'missing':'all';
try{await save();const result=await api('projects/'+pid+'/generate-batch',{kind,mode,...(kind==='image'?{required_only:true}:{})});const note=ui`本轮新增 ${result.jobs.length} 个，跳过 ${result.skipped.length} 个`;if(p.id===pid){jobs=[...new Map([...jobs,...result.jobs].map(j=>[j.id,j])).values()];render();if($('#batchMissing'))$('#batchMissing').checked=mode==='missing';if($('#batchNote')){$('#batchNote').textContent=note;$('#batchNote').title=result.skipped.map(x=>`${x.title}：${x.reason}`).join('\n')}}await refreshQueue();toast(note+(result.skipped.length?'：'+[...new Set(result.skipped.map(x=>x.reason))].join('；'):''))}catch(e){toast(e.message)}}

const pendingLookGenerations=new Set();
