async function prepareShots(operation,shotId,forceOverwrite=false){
 if(projectTextBusy()){toast(ui('请等待当前文字任务结束'));return}
 const overwrite=forceOverwrite||document.querySelector('#prepareOverwrite')?.checked||false;
 if(overwrite&&!confirm(ui('覆盖所选镜头已有的资产关联或视频提示词？剧情、台词和已有媒体保留。')))return;
 if(operation==='prepare_video'&&!confirm(ui('将连续准备镜头并生成视频；首帧方案缺图时会先生成首帧，云端可能产生费用。已有视频跳过，有待确认事项的镜头不生成。')))return;
 const buttons=[...document.querySelectorAll('[data-prepare]')];buttons.forEach(b=>b.disabled=true);
 try{await save();const job=await api('projects/'+p.id+'/prepare-shots',{operation,scope:overwrite?'all':'missing',...(shotId?{shot_ids:[shotId]}:{}),confirm_generate:operation==='prepare_video'});jobs.push(job);refreshQueue().catch(()=>{});render();toast(ui('镜头准备任务已加入队列'))}catch(e){toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}
}
function bindShotPreparation(){document.querySelectorAll('[data-prepare]').forEach(button=>{button.disabled=projectTextBusy();button.onclick=()=>prepareShots(button.dataset.prepare,button.dataset.prepareSingle?target()?.id:null)})}
function preparationActions(){return ui`<div class="shot-preparation-actions"><button class="primary" data-prepare="prepare">✧ 一键准备全部镜头</button><div class="row"><button data-prepare="assets">全部匹配资产</button><button data-prepare="prompts">全部生成视频提示词</button></div><details><summary>更多执行选项</summary><label><input type="checkbox" id="prepareOverwrite"> 覆盖已有匹配和提示词</label><button data-prepare="prepare_video">准备并生成视频</button><small>默认保留手动结果；已完成且未变化的步骤跳过。需要确认的镜头不会自动出视频。</small></details></div>`}
async function generateLook(look,button){const pid=p.id,key=pid+':'+look.id;if(pendingLookGenerations.has(key)||running(look.id,'image'))return;pendingLookGenerations.add(key);button.disabled=true;button.textContent=ui('提交中…');button.setAttribute('aria-busy','true');toast(ui('正在提交造型任务…'));try{await save();const j=await api('projects/'+pid+'/generate',{target:'look',id:look.id,kind:'image'});if(p?.id===pid){jobs.push(j);render()}toast(ui('造型任务已加入队列'));refreshQueue().catch(()=>{})}catch(e){toast(ui('造型任务提交失败：')+e.message)}finally{pendingLookGenerations.delete(key);if(p?.id===pid)render()}}
async function generate(s,kind,isAsset=false){try{const durationInput=document.querySelector('[data-field=duration]');if(kind==='video'&&durationInput&&!durationInput.reportValidity())return;await save();const j=await api('projects/'+p.id+'/generate',{id:s.id,kind,target:isAsset?'asset':'shot'});jobs.push(j);render();await refreshQueue();toast(ui('已加入任务队列，提示词保持原样'))}catch(e){toast(e.message)}}
async function upload(s){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{const f=input.files[0];if(!f)return;try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});const x=await api('projects/'+p.id+'/upload',{data});s.image=x.url;(s.versions??=[]).push({id:newResourceId(),kind:'image',url:x.url,prompt:'上传图片',created:Date.now()/1000});change();render()}catch(e){toast(e.message)}};input.click()}
async function uploadResource(resource,kind='image'){const project=p;const input=document.createElement('input');input.type='file';input.accept=kind==='audio'?'audio/*':'image/png,image/jpeg,image/webp';input.onchange=async()=>{const file=input.files[0];if(!file)return;const max=kind==='audio'?48:24;if(file.size>max*1024*1024){toast(ui('文件超过')+max+'MB');return}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const result=await api('projects/'+project.id+(kind==='audio'?'/upload-media':'/upload'),kind==='audio'?{kind,data}:{data});if(p?.id!==project.id)return;resource=frontendResources().find(x=>x.id===resource.id);if(!resource)throw Error(ui('该资源已被移除，请重新上传'));resource[kind]=result.url;if(kind==='audio')resource.audio_duration=result.duration;(resource.versions??=[]).push({id:newResourceId(),kind,url:result.url,created:Date.now()/1000,duration:result.duration,prompt:ui('上传')+(kind==='audio'?'音频':ui('图片'))});change();render()}catch(e){toast(e.message)}};input.click()}
