function lookOptimizationJob(look){return jobs.filter(j=>['optimize_look','optimize_prop'].includes(j.operation)&&j.target_id===look.id).sort((a,b)=>b.created-a.created||b.id.localeCompare(a.id))[0]}
function lookOptimizationLabel(look){if(pendingLookOptimizations.has(p.id+':'+look.id))return ui('提交中…');const job=running(look.id,'text');return job?(job.status==='queued'?ui('优化排队中…'):ui('优化中…')):(look.type==='道具'?ui('优化提示词'):ui('优化描述'))}
function dismissLookOptimization(id){dismissedLookOptimizations.add(id);try{localStorage.setItem('shotdesk:look-suggestion:'+p.id+':'+id,'dismissed')}catch{}}
function lookOptimizationDismissed(id){if(dismissedLookOptimizations.has(id))return true;try{return localStorage.getItem('shotdesk:look-suggestion:'+p.id+':'+id)==='dismissed'}catch{return false}}
function lookOptimizationPanel(look){const j=lookOptimizationJob(look);if(!j||lookOptimizationDismissed(j.id))return '';if(j.status==='failed')return ui`<div class="look-optimization-result"><small>优化失败：${esc(j.error||ui('请重试'))}，原文保留。</small></div>`;if(j.status!=='completed'||!j.result)return '';const result=j.result,applied=look.prompt===result.description,stale=look.prompt!==result.original_description||(look.generation_requirements||'')!==result.original_requirements;return ui`<div class="look-optimization-result"><b>${applied?ui('已采用优化描述'):ui('优化建议 · 原文尚未修改')}</b><textarea readonly aria-label="优化后的造型描述">${esc(result.description)}</textarea>${!result.description?ui('<small>未找到可保留的造型信息；采用将清空描述。</small>'):''}<div class="row"><button data-apply-look-optimization="${esc(j.id)}" ${applied||stale?'disabled':''}>${applied?ui('已采用'):stale?ui('描述或要求已变，请重新优化'):ui('采用并收起')}</button><button data-dismiss-look-optimization="${esc(j.id)}">${applied?ui('收起'):ui('保留原文并收起')}</button></div></div>`}
async function optimizeLookDescription(look,button){const pid=p.id,key=pid+':'+look.id;if(pendingLookOptimizations.has(key)||running(look.id,'text'))return;pendingLookOptimizations.add(key);button.disabled=true;button.textContent=ui('提交中…');try{await save();const job=await api('projects/'+pid+(look.type==='道具'?'/optimize-prop':'/optimize-look'),look.type==='道具'?{asset_id:look.id}:{look_id:look.id});if(p?.id===pid){jobs.push(job);render()}toast(ui('描述优化已加入文字任务队列，结果确认后再采用'));refreshQueue().catch(()=>{})}catch(e){toast(ui('优化描述失败：')+e.message)}finally{pendingLookOptimizations.delete(key);if(p?.id===pid)render()}}
function bindLookOptimization(container,look){container.querySelector('[data-optimize-look]').onclick=e=>optimizeLookDescription(look,e.currentTarget);const apply=container.querySelector('[data-apply-look-optimization]');if(apply)apply.onclick=()=>{const job=jobs.find(j=>j.id===apply.dataset.applyLookOptimization);if(!job?.result)return;if(look.prompt!==job.result.original_description||(look.generation_requirements||'')!==job.result.original_requirements){toast(ui('描述或出图要求已修改，请重新优化'));return}look.prompt=job.result.description;dismissLookOptimization(job.id);change();render()};const dismiss=container.querySelector('[data-dismiss-look-optimization]');if(dismiss)dismiss.onclick=()=>{dismissLookOptimization(dismiss.dataset.dismissLookOptimization);render()}}
let assetPromptPresets={};
function assetPromptControls(resource,type){const requirements=resource.generation_requirements??'';return ui`<section class="asset-prompt-settings" data-prompt-settings="${esc(resource.id)}"><label class="prompt-label">出图要求 <span>可编辑，可清空</span><textarea data-generation-requirements aria-label="出图要求">${esc(requirements)}</textarea></label><small class="prompt-explanation">${type==='prop'?ui('道具只保留自身信息，默认方形、纯灰色无缝背景；描述中的其他物品、墙面、地面仍可能被带入，可用「优化提示词」清理。'):(type==='identity'?ui('身份图用于确定脸和发型；默认是正面头肩像。'):ui('造型图用于确定全身穿着；默认是单人正面全身。'))+' '+ui('默认纯白无缝摄影背景；描述中的公寓、阳台或日照等场景词仍可能被带入。')}</small><details class="submitted-prompt"><summary>查看实际提交提示词</summary><textarea data-combined-prompt readonly aria-label="实际提交提示词">${esc(combinedAssetPrompt(resource))}</textarea><small>只提交描述＋上方出图要求，没有隐藏的构图或背景附加词。没有填写描述时无法生成。</small></details></section>`}
