function assetDescription(a){return a.type==='角色'&&a.profile&&a.profile.trim()!==(a.prompt||'').trim()?[a.prompt,a.profile].filter(Boolean).join('\n\n'):a.prompt||a.profile||''}
let assetCategory='角色',assetSelected=null;const assetLookSelection={},assetVoiceSelection={},lookHistoryScroll=new Map();
function ensureCharacter(a){if(a.generation_requirements==null)a.generation_requirements=assetPromptPresets.identity||'';for(const l of a.looks||[])if(l.generation_requirements==null)l.generation_requirements=assetPromptPresets.look||'';if(!a.looks?.length)a.looks=[{id:a.id+'-default-look',name:'默认造型',prompt:assetPromptPresets.default_look_description||'',generation_requirements:assetPromptPresets.look||'',versions:[]}];a.default_look_id??=a.looks[0].id;if(!a.voices?.length)a.voices=[{id:a.id+'-default-voice',name:'默认声线',asset_id:a.voice_asset_id||null}];a.default_voice_id??=a.voices[0].id;if(!a.looks.some(l=>l.id===assetLookSelection[a.id]))delete assetLookSelection[a.id];if(!a.voices.some(v=>v.id===assetVoiceSelection[a.id]))delete assetVoiceSelection[a.id]}
